async def _get_installer():
    """获取 ToolInstaller（优先取 AgentApp 上的实例，否则降级自建）。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()

    installer = getattr(app, 'tool_installer', None) if app else None
    if installer is not None:
        return installer

    global _fallback_installer
    if _fallback_installer is None:
        from agent_runtime.core.tool_installer import ToolInstaller
        from agent_runtime.core.tool_models import ToolDatabase
        from agent_runtime.core.tool_registry import ToolRegistry

        db_path = Path.home() / '.openchiip-harness' / 'data' / 'tools.db'
        db = ToolDatabase(str(db_path))
        installer = ToolInstaller(
            registry=ToolRegistry(),
            db=db,
            subagent_manager=getattr(app, 'subagent_manager', None),
            config=getattr(app, 'config', None),
            mcp_tools=getattr(app, 'tools', None),
        )
        await installer.initialize()
        _fallback_installer = installer
        logger.info('使用降级 ToolInstaller（AgentApp 未提供实例）')
    return _fallback_installer


def _mask_secret(value: str) -> str:
    """密钥脱敏（保留前 4 + 后 4 位）。"""
    text = str(value or '')
    if not text:
        return ''
    if len(text) <= 12:
        return '****'
    return text[:4] + '****' + text[-4:]


def _parse_env_payload(body: dict) -> dict:
    """兼容 {"env_vars": {...}} 与扁平 {"KEY": "VALUE"} 两种请求体。"""
    if not isinstance(body, dict):
        return {}
    nested = body.get('env_vars')
    if isinstance(nested, dict):
        return nested
    return {k: v for k, v in body.items()
            if k != 'env_vars' and isinstance(k, str)}


