@router.get('')
async def list_tools(category: str = ''):
    """统一工具列表（内置注册表 + 平台下发 + MCP 工具三来源合并）。

    Query:
        category: 可选，按分类过滤（ai-agent/mcp/builtin/dev）
    """
    installer = await _get_installer()
    try:
        items = await installer.list_tools_view()
    except Exception as exc:
        logger.exception('获取工具列表失败')
        return {'error': '获取工具列表失败: %s' % exc}

    if category:
        items = [i for i in items if i.get('category') == category]
    return items


@router.post('/reload')
async def reload_platform_tools():
    """重新加载平台下发的 tools.json，合并安装记录。"""
    installer = await _get_installer()
    try:
        summary = await installer.reload_platform_tools()
        return {'success': not summary.get('errors'), **summary}
    except Exception as exc:
        logger.exception('加载平台工具失败')
        return {'success': False, 'error': str(exc)}


@router.get('/{key}')
async def get_tool(key: str):
    """单个工具详情（含实时 probe 结果）；未知 key 回退到 MCP 工具详情。"""
    installer = await _get_installer()
    try:
        view = await installer.get_tool_view(key)
    except Exception as exc:
        logger.exception('获取工具详情失败: %s', key)
        return {'error': str(exc)}

    if view is not None:
        return view

    # 回退：既有 MCP 工具（保留旧行为）
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if app:
        for tool in app.tools.list_tools():
            if tool.get('key') == key or tool.get('name') == key:
                return tool
    return {'error': '工具 %s 不存在' % key}


@router.post('/{key}/install')
async def install_tool(key: str, req: InstallRequest = None):
    """一键安装工具（长耗时操作，前端需配置较大超时）。

    请求体可选: {"version": "22"} — 指定安装版本（仅对声明了 versions 的工具生效）
    """
    installer = await _get_installer()
    version = req.version if req else None
    logger.info('收到安装请求: %s version=%s', key, version or '-')
    try:
        result = await installer.install(key, version=version)
    except Exception as exc:
        logger.exception('安装工具异常: %s', key)
        return {'success': False, 'error': str(exc)}
    payload = result.to_dict()
    if not result.success:
        payload['error'] = result.message
    return payload


@router.delete('/{key}/install')
async def uninstall_tool(key: str):
    """卸载工具。"""
    installer = await _get_installer()
    logger.info('收到卸载请求: %s', key)
    try:
        result = await installer.uninstall(key)
    except Exception as exc:
        logger.exception('卸载工具异常: %s', key)
        return {'success': False, 'error': str(exc)}
    payload = result.to_dict()
    if not result.success:
        payload['error'] = result.message
    return payload


@router.post('/{key}/probe')
async def probe_tool_api(key: str):
    """手动探测工具可用性（跳过缓存）。"""
    installer = await _get_installer()
