@router.patch('/{key}/env')
async def set_tool_env(key: str, request: Request):
    """配置工具环境变量（落库 + 写入 agent.env + 注入当前进程）。"""
    try:
        body = await request.json()
    except Exception:
        body = {}
    env_vars = _parse_env_payload(body)
    if not env_vars:
        return {'success': False, 'error': '未提供有效的环境变量'}

    installer = await _get_installer()
    try:
        ok = await installer.set_env_vars(key, env_vars)
    except Exception as exc:
        logger.exception('配置环境变量异常: %s', key)
        return {'success': False, 'error': str(exc)}

    if not ok:
        return {'success': False,
                'error': '环境变量保存失败（工具不存在或未声明该变量）'}
    logger.info('工具 %s 环境变量已更新: %s', key, ', '.join(sorted(env_vars)))
    return {'success': True, 'key': key,
            'configured': sorted(k for k, v in env_vars.items() if v)}


@router.get('/{key}/env')
async def get_tool_env(key: str):
    """查看工具环境变量配置状态（值脱敏）。"""
    installer = await _get_installer()
    try:
        saved = await installer.get_env_vars(key)
        view = await installer.get_tool_view(key)
    except Exception as exc:
        logger.exception('读取环境变量异常: %s', key)
        return {'error': str(exc)}

    declared = (view or {}).get('env_config_keys') or list(saved.keys())
    return {
        'key': key,
        'env_config_keys': declared,
        'env_configured': {name: bool(saved.get(name)) for name in declared},
        'env_masked': {name: _mask_secret(value)
                       for name, value in saved.items() if value},
    }


@router.post('/{key}/enable')
async def enable_tool(key: str):
    """启用工具（探测可用则热注册 Provider）。"""
    installer = await _get_installer()
    try:
        ok = await installer.enable(key)
    except Exception as exc:
        logger.exception('启用工具异常: %s', key)
        return {'success': False, 'error': str(exc)}
    if not ok:
        return {'success': False, 'error': '工具 %s 不存在' % key}
    view = await installer.get_tool_view(key)
    return {'success': True, 'key': key, 'enabled': True,
            'provider_registered': bool((view or {}).get('provider_registered'))}


@router.post('/{key}/disable')
async def disable_tool(key: str):
    """禁用工具（热注销 Provider）。"""
    installer = await _get_installer()
    try:
        ok = await installer.disable(key)
    except Exception as exc:
        logger.exception('禁用工具异常: %s', key)
        return {'success': False, 'error': str(exc)}
    if not ok:
        return {'success': False, 'error': '工具 %s 不存在' % key}
    return {'success': True, 'key': key, 'enabled': False,
            'provider_registered': False}


