@router.post('/register')
async def register_tool(req: ToolRegisterRequest):
    """注册 MCP 工具。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    try:
        app.tools.register(req.name, req.command, req.description)
        return {'success': True, 'registered': req.name}
    except Exception as e:
        return {'success': False, 'error': str(e)}


@router.delete('/{tool_id}')
async def unregister_tool(tool_id: str):
    """注销 MCP 工具。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    try:
        app.tools.unregister(tool_id)
        return {'success': True, 'removed': tool_id}
    except Exception as e:
        return {'success': False, 'error': str(e)}


@router.post('/{tool_id}/test')
async def test_tool(tool_id: str, req: ToolTestRequest):
    """测试 MCP 工具调用。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    try:
        result = app.tools.dispatch_tool_call(tool_id, req.args)
        return {'success': True, 'result': result}
    except Exception as e:
        return {'success': False, 'error': str(e)}
